{"implementation": "def solve(case):
    refinement = case["refinement"]
    edges = case["edges"]
    # Build members: group -> list of vertices
    members = {}
    for vertex, group in refinement.items():
        members.setdefault(group, []).append(vertex)
    # Aggregate edge weights per group pair
    agg = {}
    for u, v, w in edges:
        gu = refinement[u]
        gv = refinement[v]
        key = (gu, gv)
        agg[key] = agg.get(key, 0) + w
    aggregate_edges = [[k[0], k[1], v] for k, v in agg.items()]
    return {"members": members, "aggregate_edges": aggregate_edges}"}
